const staticData = $getWorkflowStaticData('global');

const REQUERIDOS = ['nombrePaciente', 'telefono', 'correo', 'servicio', 'fechaInicio'];

const NOMBRES = {
  nombrePaciente: 'el nombre completo del paciente',
  telefono: 'el teléfono',
  correo: 'el correo electrónico',
  servicio: 'el servicio que necesitas',
  fechaInicio: 'la fecha y hora'
};

// Un borrador a medio llenar caduca a los 30 minutos.
const VIGENCIA_MS = 30 * 60 * 1000;

for (const item of $input.all()) {
  const texto = item.json.output || '';
  const chatId = $('Telegram Trigger').item.json.message.chat.id;
  const mensajeUsuario = String($('Telegram Trigger').item.json.message.text || '');
  const clave = 'borrador_' + chatId;

  // 0. Boton de panico: /reset borra el borrador de este chat
  if (/^\/?(reset|reiniciar|empezar de nuevo)$/i.test(mensajeUsuario.trim())) {
    delete staticData[clave];
    item.json.accion = 'otro';
    item.json.respuesta = 'Listo, empecemos de nuevo. ¿En que te ayudo?';
    item.json.datos = {};
    item.json.faltan = [];
    continue;
  }

  // 1. Extraer el JSON que devolvio el modelo
  const match = texto.match(/\{[\s\S]*\}/);
  let p = { accion: 'otro', datos: {}, respuesta: texto };

  if (match) {
    try {
      p = JSON.parse(match[0]);
    } catch (e) {
      p = { accion: 'otro', datos: {}, respuesta: 'No entendi, ¿me lo repites?' };
    }
  }

  // 2. Fusionar con lo que ya se habia recogido antes.
  //    Sin _ts o con _ts vencido = borrador viejo, se descarta.
  const guardado = staticData[clave];
  const vigente = guardado
    && guardado._ts
    && (Date.now() - guardado._ts) < VIGENCIA_MS;

  if (guardado && !vigente) {
    delete staticData[clave];
  }

  const previo = vigente ? guardado : {};
  const datos = Object.assign({}, previo);
  delete datos._ts;

  for (const clave2 of Object.keys(p.datos || {})) {
    const valor = p.datos[clave2];
    if (valor && String(valor).trim() !== '') {
      datos[clave2] = valor;
    }
  }

  // 3. Revisar que falta
  const faltan = REQUERIDOS.filter(k => !datos[k]);
  const esFlujoCita = (p.accion === 'agendar' || p.accion === 'faltan_datos');

  if (esFlujoCita && faltan.length === 0) {
    // Estan los 5 datos: agendar y limpiar el borrador
    item.json.accion = 'agendar';
    item.json.respuesta = 'Dame un momento, estoy revisando la disponibilidad.';
    delete staticData[clave];

  } else if (esFlujoCita) {
    // Faltan datos: guardar el borrador con su marca de tiempo
    staticData[clave] = Object.assign({}, datos, { _ts: Date.now() });

    const lista = faltan.map(k => NOMBRES[k]);
    const enumerado = lista.length === 1
      ? lista[0]
      : lista.slice(0, -1).join(', ') + ' y ' + lista[lista.length - 1];

    item.json.accion = 'faltan_datos';
    item.json.respuesta = 'Para continuar necesito ' + enumerado + '.';

  } else {
    // consultar, drive, otro: no toca el borrador
    item.json.accion = p.accion || 'otro';
    item.json.respuesta = p.respuesta || '';
    item.json.datos = p.datos || {};
    item.json.faltan = [];
    continue;

  }

  item.json.datos = datos;
  item.json.faltan = faltan;

}

return $input.all();

const out = [];
for (const item of $input.all()) {
const datos = item.json.datos || {};
const hoy = DateTime.now().setZone('America/Bogota');
let desde = String(datos.fechaConsulta || '').substring(0, 10);
let hasta = String(datos.fechaConsultaFin || '').substring(0, 10);
// Si el agente no dio fecha valida, usar hoy
if (!/^\d{4}-\d{2}-\d{2}$/.test(desde)) {
desde = hoy.toFormat('yyyy-MM-dd');
}
if (!/^\d{4}-\d{2}-\d{2}$/.test(hasta)) {
hasta = desde;
}
// Si vienen al reves, intercambiar
if (hasta < desde) {
const tmp = desde; desde = hasta; hasta = tmp;
}
item.json.desde = desde;
item.json.hasta = hasta;
out.push(item);
}
return out;
// Si la IA detectó "mañana", calcula la fecha correspondiente; si ya dio una fecha (YYYY-MM-DD), consérvala:
let fechaConsulta = $input.first().json.fecha;

if (!fechaConsulta || fechaConsulta.toLowerCase() === 'mañana') {
    const manana = new Date();
    manana.setDate(manana.getDate() + 1);
    fechaConsulta = manana.toISOString().split('T')[0];
}

return [{ json: { fecha: fechaConsulta } }];

for (const item of $input.all()) {
  const status = item.json.statusCode;
  const desde = $('Calcular Rango Fechas').item.json.desde;
  const body = item.json.body;

  if (status !== 200) {
    item.json.respuesta = 'No pude consultar la agenda en este momento.';
    continue;
  }

    // Caso ADMIN: array de citas
  if (Array.isArray(body)) {
    if (body.length === 0) {
      item.json.respuesta = 'No hay citas agendadas para el ' + desde + '.';
      continue;
    }

    const ESTADOS = {
      PRE_RESERVA: 'Pendiente de pago',
      CONFIRMADA: 'Confirmada',
      CANCELADA: 'Cancelada',
      PENDIENTE: 'Pendiente de pago'
    };

    const lineas = body
      .sort((a, b) => String(a.hora).localeCompare(String(b.hora)))
      .map(c => '#' + c.idReserva + '  ' + c.hora + '  ' + c.paciente
        + '\n     ' + c.servicio
        + '\n     ' + (ESTADOS[c.estado] || c.estado));
    item.json.respuesta = 'Agenda del ' + desde + '\n\n' + lineas.join('\n\n')
      + '\n\nTotal: ' + body.length + ' cita(s).';
    continue;
  }

  // Caso CLIENTE: objeto con disponibles
  const libres = (body && body.disponibles) || [];
  if (libres.length === 0) {
    item.json.respuesta = (body && body.mensaje)
      || 'No hay horarios libres el ' + desde + '. Dime otra fecha.';
  } else {
    item.json.respuesta = 'Horarios disponibles el ' + desde + ':\n\n'
      + libres.join('  •  ');
  }
}

return $input.all();

