const res = $('Cancelar Cita').item.json;
const status = res.statusCode;
const body = res.body || {};

for (const item of $input.all()) {
  if (status === 200) {
    item.json.respuesta = body.mensaje || 'Cita cancelada.';
  } else if (status === 404) {
    item.json.respuesta = 'No encontre esa cita. Consulta la agenda para ver el numero correcto.';
  } else {
    item.json.respuesta = 'No pude cancelar la cita en este momento. Intenta de nuevo.';
  }
}

return $input.all();

const res = $('Reprogramar Cita').item.json;
const body = res.body || {};

for (const item of $input.all()) {
  item.json.respuesta = body.mensaje || 'Cita reprogramada.';
}

return $input.all();

const res = $('Reprogramar Cita').item.json;
const status = res.statusCode;
const body = res.body || {};

let texto = body.mensaje || 'No pude reprogramar esa cita.';

if (status === 404) {
  texto = 'No encontre esa cita. Consulta la agenda para ver el numero correcto.';
}

const alt = body.alternativas || [];
if (alt.length) {
  texto += '\n\nTe sirve a las: '
    + alt.map(f => String(f).substring(11, 16)).join('  •  ');
}

for (const item of $input.all()) {
  item.json.respuesta = texto;
}

return $input.all();

const carpetaPedida = $('Parsear salida').item.json.datos.carpeta || '';
const PERMITIDAS = ['administracion', 'clientes', 'finanzas', 'servicios', 'comprobantes'];

const normalizar = s => String(s).toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '');

if (!PERMITIDAS.includes(normalizar(carpetaPedida))) {
  return [{ json: { respuesta: 'No tengo acceso a esa carpeta. Puedo mostrarte: '
    + 'Administracion, Clientes, Finanzas, Servicios o Comprobantes.' }}];
}

const archivos = $input.all().filter(i => i.json && i.json.name);

const texto = archivos.length === 0
  ? 'La carpeta ' + carpetaPedida + ' esta vacia.'
  : 'Archivos en ' + carpetaPedida + ':\n\n'
    + archivos.slice(0, 20).map(a => '• ' + a.json.name).join('\n')
    + (archivos.length > 20 ? '\n\n(' + archivos.length + ' archivos en total)' : '');

return [{ json: { respuesta: texto } }];
